el &lt;- 0.05; # 95% confidence meanVal &lt;- mean(nycDat$UNEMP_RATE); lisaRslt %&lt;&gt;% tibble::as_tibble() %&gt;% magrittr::set_colnames(c(&quot;Ii&quot;,&quot;E.Ii&quot;,&quot;Var.Ii&quot;,&quot;Z.Ii&quot;,&quot;Pr()&quot;)) %&gt;% dplyr::mutate(coType = dplyr::case_when( `Pr()` &gt; 0.05 ~ &quot;Insignificant&quot;, `Pr()` &lt;= 0.05 &amp; Ii &gt;= 0 &amp; nycDat$UNEMP_RATE &gt;= meanVal ~ &quot;HH&quot;, `Pr()` &lt;= 0.05 &amp; Ii &gt;= 0 &amp; nycDat$UNEMP_RATE &lt; meanVal ~ &quot;LL&quot;, `Pr()` &lt;= 0.05 &amp; Ii &lt; 0 &amp; nycDat$UNEMP_RATE &gt;= meanVal ~ &quot;HL&quot;, `Pr()` &lt;= 0.05 &amp; Ii &lt; 0 &amp; nycDat$UNEMP_RATE &lt; meanVal ~ &quot;LH&quot; )) # Now add this coType to original sf data nycDat$coType &lt;- lisaRslt$coType %&gt;% tidyr::replace_na(&quot;Insignificant&quot;) ggplot(nycDat) + geom_sf(aes(fill=coType),color = &#39;lightgrey&#39;) + scale_fill_manual(values = c(&#39;red&#39;,&#39;brown&#39;,&#39;NA&#39;,&#39;blue&#39;,&#39;cyan&#39;), name=&#39;Clusters &amp; 
Outliers&#39;) + labs(title = &quot;Unemployment Rate at Census Tract Level&quot;) The HH, LL clusters suggest that there are local clusters of high unemployment areas like Bronx and Coney Island. Similarly, there are also clusters of low unemployment areas such as upper west and upper east areas in Manhattan. From the plot, it is also clear that some outliers, i.e., HL or LH, are present in the unemployment distribution at 95% confidence level. These census tracts have high or low unemployment rates. Their neighbors, however, have opposite low or high rates. Obviously, the local Moran’s I or LISA provides more detailed and local information about spatial autocorrelation. More importantly, they can identify those local clusters (hotspots, coldspots) and outliers. A few more examples from the same dataset. # Define this as a function, which could save some space. plotCOType &lt;- function(varName, titleText, cols=1:5) { varVals &lt;- nycDat[[varName]] %&gt;% as.character() %&gt;% as.numeric() lisaRslt &lt;- spdep::localmoran(varVals, nycNbList, zero.policy = TRUE, na.action = na.exclude) significanceLevel &lt;- 0.05; # 95% confidence meanVal &lt;- mean(varVals, na.rm=TRUE); lisaRslt %&lt;&gt;% tibble::as_tibble() %&gt;% magrittr::set_colnames(c(&quot;Ii&quot;,&quot;E.Ii&quot;,&quot;Var.Ii&quot;,&quot;Z.Ii&quot;,&quot;Pr(z &gt; 0)&quot;)) %&gt;% dplyr::mutate(coType = dplyr::case_when( `Pr(z &gt; 0)` &gt; 0.05 ~ &quot;Insignificant&quot;, `Pr(z &gt; 0)` &lt;= 0.05 &amp; Ii &gt;= 0 &amp; varVals &gt;= meanVal ~ &quot;HH&quot;, `Pr(z &gt; 0)` &lt;= 0.05 &amp; Ii &gt;= 0 &amp; varVals &lt; meanVal ~ &quot;LL&quot;, `Pr(z &gt; 0)` &lt;= 0.05 &amp; Ii &lt; 0 &amp; varVals &gt;= meanVal ~ &quot;HL&quot;, `Pr(z &gt; 0)` &lt;= 0.05 &amp; Ii &lt; 0 &amp; varVals &lt; meanVal ~ &quot;LH&quot; )) # Now add this coType to original sf data nycDat$coType &lt;- lisaRslt$coType %&gt;% tidyr::replace_na(&quot;Insignificant&quot;) ggplot(nycDat) + geom_sf(aes(fill=coType),color = &#39;lightgrey&#39;) + scale_fill_manual(values = c(&#39;red&#39;,&#39;brown&#39;,&#39;NA&#39;,&#39;blue&#39;,&#39;cyan&#39;)[cols], name=&#39;Clusters &amp; 
Outliers&#39;) + labs(title = titleText) } plotCOType(&#39;medianinco&#39;, &quot;Median Household Income at Census Tract Level&quot;) plotCOType(&#39;asian&#39;, &#39;Asian Population at Census Tract Level&#39;, c(1,3,4,5)) 4.1.3 Bivariate Moran’s I (Spatial Association) This subsection is still under development. Use with caution. While it is very useful to examine the spatial autocorrelation of one single variable globally and locally, more often we are wondering if one variable x is spatially associated with another variable y in its spatial neighbors. For example, the presence of a police station is very likely to reduce the crime rate of the block where the station is located. But how does the presence of the station influence neighboring blocks? With bivariate local Moran’s I, the spatial association of the presence of a police station and the crime rates in neighboring blocks can be formally tested. Here we use two variables in the dataset to explore the bivariate case of Moran statistics. One variable is Unemployment and the other is the percentage of struggling population. 4.1.3.1 Global Bivariate Moran’s I First, Global Bivariate Moran is a measure of autocorrelation of X with the spatial lag of Y. As such, the resultant measure may overestimate the amount of spatial autocorrelation which may be a product of the inherent correlation of X and Y. The concept of bivariate spatial correlation is complex and often misinterpreted. It is typically considered to be the correlation between one variable and the spatial lag of another variable, as originally implemented in the precursor of GeoDa (e.g., as described in Anselin, Syabri, and Smirnov 2002). However, this does not take into account the inherent correlation between the two variables. More precisely, the bivariate spatial correlation is between \(x_i\) and \(\sum_j {w_{ij}y_j}\), but does not take into account the correlation between \(x_i\) and \(y_i\), i.e., between the two variables at the same location. — GeoDa Center nycNearestNBList &lt;- knn2nb(knearneigh(nycDat %&gt;% sf::st_point_on_surface(), k=1)) %&gt;% spdep::nb2listw() #&gt; Warning: st_point_on_surface assumes attributes are constant over geometries #&gt; Warning in st_point_on_surface.sfc(st_geometry(x)): st_point_on_surface may not #&gt; give correct results for longitude/latitude data #&gt; Warning in knn2nb(knearneigh(nycDat %&gt;% sf::st_point_on_surface(), k = 1)): #&gt; neighbour object has 606 sub-graphs moranBVboot &lt;- spdep::moran_bv(x = datX &lt;- nycDat$UNEMP_RATE, y = datY &lt;- (nycDat$struggling/(1+nycDat$poptot)) %&gt;% as.numeric(), listw = nycNearestNBList, nsim = 500) # Tend to overestimate the association print(moranBVboot); #&gt; #&gt; DATA PERMUTATION #&gt; #&gt; #&gt; Call: #&gt; boot(data = xx, statistic = bvm_boot, R = nsim, sim = &quot;permutation&quot;, #&gt; listw = listw, parallel = parallel, ncpus = ncpus, cl = cl) #&gt; #&gt; #&gt; Bootstrap Statistics : #&gt; original bias std. error #&gt; t1* 0.1993504 -0.2003289 0.02102869 cat(&quot;
&quot;) boot::boot.ci(moranBVboot, conf=c(0.99, 0.95, 0.9), type=&quot;basic&quot;) %&gt;% print() #&gt; BOOTSTRAP CONFIDENCE INTERVAL CALCULATIONS #&gt; Based on 500 bootstrap replicates #&gt; #&gt; CALL : #&gt; boot::boot.ci(boot.out = moranBVboot, conf = c(0.99, 0.95, 0.9), #&gt; type = &quot;basic&quot;) #&gt; #&gt; Intervals : #&gt; Level Basic #&gt; 99% ( 0.3447, 0.4577 ) #&gt; 95% ( 0.3577, 0.4411 ) #&gt; 90% ( 0.3641, 0.4354 ) #&gt; Calculations and Intervals on Original Scale #&gt; Some basic intervals may be unstable plot(moranBVboot) The global bivariate Moran’s statistic is 0.199. It also has a bias of -0.200, meaning the estimated statistic is likely lower than the real statistic, using the bootstrapping approach. With the bootstrapping method, the confidence internals show higher values. As these intervals do not include zero, the bivariate Moran’s I is significant. The plot also shows that the t0 - the observed bivariate Moran’s I statistic shown with the vertical dashed line - is far away from the statistics calculated from randomly selected samples via bootstrapping, meaning the observed statistic is different from what are expected from the null hypothesis of bivariate Moran’s I being zero. The histogram and QQ plots also show that the statistics from random samples follow a normal distribution, verifying the validity of drawing the conclusion about the significance of the observed bivariate Moran’s I. All these suggest that there is significant positive correlation between X (unemployment) and lagged Y (rate of struggling population). Despite such statistical significance, the interpretation of bivariate Moran’s I is not quite straightforward in real-world applications. It is more often applied to temporal “neighbors”, instead of spatial “neighbors.” localMoranBV &lt;- spdep::localmoran_bv(x = datX, y = datY, listw = nycNearestNBList, nsim = 500) %&gt;% as.data.frame() # To plot as HH, HL, LH, LL # refer # listw2mat, nb2mat functions to get a matrix mat # apply the matrix to scaled y mat%*%scale(y) &gt; 0 high &lt; 0 low meanVal &lt;- nycNearestNBList %&gt;% listw2mat() %*% scale(datY) %&gt;% as.vector() significanceLevel &lt;- 0.05; # 95% confidence #localMoranBV$datY &lt;- datY #localMoranBV$meanVal &lt;- meanVal localMoranBV %&lt;&gt;% tibble::as_tibble() %&gt;% magrittr::set_colnames(c(&quot;Ibvi&quot;,&quot;E.Ibvi&quot;,&quot;Var.Ibvi&quot;,&quot;Z.Ibvi&quot;,&quot;P&quot;, &quot;PSim&quot;, &quot;PFoldedSim&quot;)) %&gt;% dplyr::mutate(lmbvType = dplyr::case_when( `PSim` &gt; 0.05 ~ &quot;Insignificant&quot;, `PSim` &lt;= 0.05 &amp; Ibvi &gt;= 0 &amp; datY &gt;= meanVal ~ &quot;HH&quot;, `PSim` &lt;= 0.05 &amp; Ibvi &gt;= 0 &amp; datY &lt; meanVal ~ &quot;LL&quot;, `PSim` &lt;= 0.05 &amp; Ibvi &lt; 0 &amp; datY &gt;= meanVal ~ &quot;HL&quot;, `PSim` &lt;= 0.05 &amp; Ibvi &lt; 0 &amp; datY &lt; meanVal ~ &quot;LH&quot; )) # Now add this lmbvType to original sf data nycDat$lmbvType &lt;- localMoranBV$lmbvType %&gt;% tidyr::replace_na(&quot;Insignificant&quot;) ggplot(nycDat) + geom_sf(aes(fill=lmbvType),color = &#39;lightgrey&#39;) + scale_fill_manual(values = c(&#39;red&#39;,&#39;brown&#39;,&#39;NA&#39;,&#39;blue&#39;,&#39;cyan&#39;)[1:5], name=&#39;Clusters &amp; 
Outliers&#39;) + labs(title = &quot;Local Bivariate Moran&#39;s I &quot;) The Local Bivariate Moran’s I can produce similar outputs as Local Moran’s I. However, the interpretation is not the same. Once more, this is the local correlation between X, unemployment, and the lagged Y, the percentage of “suffering” population in the neighboring tracts. subDat &lt;- nycDat %&gt;% dplyr::select(ntaname, poptot, UNEMP_RATE, struggling, lmbvType); mapview::mapview(x = subDat, map.types = c(&quot;CartoDB.Positron&quot;, &quot;CartoDB.DarkMatter&quot;, &quot;OpenStreetMap&quot;, &quot;Esri.WorldImagery&quot;), zcol=&#39;lmbvType&#39;, col.regions = c(&#39;red&#39;,&#39;brown&#39;,&#39;NA&#39;,&#39;blue&#39;,&#39;cyan&#39;)[1:5], layer.name = &#39;Clusters &amp; Outliers&#39;) # For point counts/occurrences/incidents data # spdep::local_joincount_bv() Like many other spatial measures, global and local Moran’s I are sensitive to geographic scales. While no outliers exist at census tract level for these variables, they may surface when being examined at a coarser scale such as the neighborhood level. 4.2 Spatial Error and Lag Models With the presence of spatial autocorrelation, we need to address its possible influence on simple linear regression models that assume spatial independence. Spatial regression models are specifically developed to achieve this. Spatial regression models are statistical models that account for the presence of spatial effects, i.e., spatial autocorrelation (or more generally spatial dependence) and/or spatial heterogeneity. With R, we can run Ordinary Least Squares models using lm or other generalized linear regression using glm. Using spdep package, we can also obtain spatial diagnostics like Moran’s I. While there are many other options, we can use spdep to estimate a model with a spatially lagged dependent variable (spatial lag model) and a spatial autoregressive process for the error term (spatial error model). — Adapted from GeoDa documentation 4.2.1 Spatial Error Model Spatial error autocorrelation arises if error terms are correlated across observations, i.e., the error of an observation affects the errors of its neighbors. It is similar to serial correlation in time series analysis and leaves OLS coefficients unbiased but renders them inefficient. Because it’s such a bothersome problem, spatial errors is also called “nuisance dependence in the error.” There are a number of instances in which spatial error can arise. For example, similar to what can happen in time series, a source of correlation may come from unmeasured variables that are related through space. Correlation can also arise from aggregation of spatially correlated variables and systematic measurement error. So what to do if there is good reason to believe that there is spatial error? Maybe the most famous test is Moran’s I which is based on the regression residuals and is also related to Moran’s scatterplot of residuals which can be used to spot the problem graphically. There are other statistics like Lagrange multiplier and likelihood ratio tests, and each of them has different ways of getting at the same problem. If there is good reason to believe that spatial error is a problem, then the way forward is either model the error directly or to use autoregressive methods. In any case it’s probably a good idea to assess whether spatial error might apply to the research problem. Because of it’s effect on OLS, there might be a better way to estimate the coefficients that we are interested in, and the results might improve quite a bit. — James Greiner, Harvard Social Science Statistics Blog The spatial error model handles the spatial autocorrelation in the residuals. The idea is that such errors (residuals from regression) are autocorrelated in that the error from one spatial feature can be modeled as a weighted average of the errors of its neighbors. In other words, such errors have spatial autocorrelation. This model can be expressed as: \[ {\mathbf y} = {\mathbf X}{\mathbf  eta} + {\mathbf u}, \qquad {\mathbf u} = \lambda_{\mathrm{Err}} {\mathbf W} {\mathbf u} + {\mathbf \varepsilon} \] where \({\mathbf y}\) is an \((N 	imes 1)\) vector of observations on a response variable taken at each of \(N\) locations, \({\mathbf X}\) is an \((N 	imes k)\) matrix of covariates, \({\mathbf  eta}\) is a \((k 	imes 1)\) vector of parameters, \({\mathbf u}\) is an \((N 	imes 1)\) spatially autocorrelated disturbance vector, \({\mathbf \varepsilon}\) is an \((N 	imes 1)\) vector of independent and identically distributed disturbances and \(\lambda_{\mathrm{Err}}\) is a scalar spatial parameter. The following code does an OLS and test whether spatial autocorrelation is present in the residuals. # Prepare data: covert some factors to numeric values nycDat %&lt;&gt;% dplyr::mutate(medianage = medianage %&gt;% as.character() %&gt;% as.numeric(), househol_1 = househol_1 %&gt;% as.character() %&gt;% as.numeric()) # olsRslt &lt;- lm(nycDat$popunemplo ~ nycDat$popinlabou + # nycDat$onlylessth + nycDat$master + # nycDat$africaninl + nycDat$asianinlab + # nycDat$hispanicin + nycDat$medianage, # data = nycDat) # summary(olsRslt) # Create a simple linear regression on unemployed population olsRslt &lt;- lm(log(popunemplo +1) ~ log(1+popinlabou) + log(1+onlylessth) + log(1+master) + log(1+africaninl) + log(1+asianinlab) + log(1+hispanicin) + nycDat$medianage, data = nycDat) summary(olsRslt) #&gt; #&gt; Call: #&gt; lm(formula = log(popunemplo + 1) ~ log(1 + popinlabou) + log(1 + #&gt; onlylessth) + log(1 + master) + log(1 + africaninl) + log(1 + #&gt; asianinlab) + log(1 + hispanicin) + nycDat$medianage, data = nycDat) #&gt; #&gt; Residuals: #&gt; Min 1Q Median 3Q Max #&gt; -4.6967 -0.2451 0.0518 0.3223 1.9265 #&gt; #&gt; Coefficients: #&gt; Estimate Std. Error t value Pr(&gt;|t|) #&gt; (Intercept) -1.983558 0.148840 -13.327 &lt; 2e-16 *** #&gt; log(1 + popinlabou) 0.731806 0.027352 26.755 &lt; 2e-16 *** #&gt; log(1 + onlylessth) 0.185133 0.015073 12.283 &lt; 2e-16 *** #&gt; log(1 + master) -0.036226 0.013619 -2.660 0.007876 ** #&gt; log(1 + africaninl) 0.082545 0.005890 14.015 &lt; 2e-16 *** #&gt; log(1 + asianinlab) -0.015196 0.006458 -2.353 0.018709 * #&gt; log(1 + hispanicin) 0.040066 0.011579 3.460 0.000551 *** #&gt; nycDat$medianage 0.003001 0.001888 1.589 0.112124 #&gt; --- #&gt; Signif. codes: 0 &#39;***&#39; 0.001 &#39;**&#39; 0.01 &#39;*&#39; 0.05 &#39;.&#39; 0.1 &#39; &#39; 1 #&gt; #&gt; Residual standard error: 0.5168 on 2116 degrees of freedom #&gt; (42 observations deleted due to missingness) #&gt; Multiple R-squared: 0.6931, Adjusted R-squared: 0.6921 #&gt; F-statistic: 682.8 on 7 and 2116 DF, p-value: &lt; 2.2e-16 # Derive the residuals from the regression. Need to handle those missed values lmResiduals &lt;- rep(0, length(nycDat$popunemplo)) resIndex &lt;- olsRslt$residuals %&gt;% names() %&gt;% as.integer(); lmResiduals[resIndex] &lt;- olsRslt$residuals # Test if there is spatial autocorrelation in the regression residuals (errors). nycNbList %&gt;% spdep::moran.test(lmResiduals, ., zero.policy = TRUE) #&gt; #&gt; Moran I test under randomisation #&gt; #&gt; data: lmResiduals #&gt; weights: . #&gt; n reduced by no-neighbour observations #&gt; #&gt; Moran I statistic standard deviate = 10.285, p-value &lt; 2.2e-16 #&gt; alternative hypothesis: greater #&gt; sample estimates: #&gt; Moran I statistic Expectation Variance #&gt; 0.1283881833 -0.0004625347 0.0001569522 The Moran’s test shows that the residuals from linear regression have statistically significant positive spatial autocorrelation. The Moran’s I is 0.128 and the p-value &lt; 0.01. With that, we can run a spatial error model to take such autocorrelation into account. # use spdep package to run the spatial error model # Use spatialreg::errorsarlm to run the same model serrRslt &lt;- spatialreg::errorsarlm(log(popunemplo +1) ~ log(1+popinlabou) + log(1+onlylessth) + log(1+master) + log(1+africaninl) + log(1+asianinlab) + log(1+hispanicin) + medianage, data = nycDat, listw = nycNbList, zero.policy = TRUE, na.action = na.omit); summary(serrRslt) #&gt; #&gt; Call:spatialreg::errorsarlm(formula = log(popunemplo + 1) ~ log(1 + #&gt; popinlabou) + log(1 + onlylessth) + log(1 + master) + log(1 + #&gt; africaninl) + log(1 + asianinlab) + log(1 + hispanicin) + #&gt; medianage, data = nycDat, listw = nycNbList, na.action = na.omit, #&gt; zero.policy = TRUE) #&gt; #&gt; Residuals: #&gt; Min 1Q Median 3Q Max #&gt; -4.526909 -0.244982 0.055031 0.300734 1.897656 #&gt; #&gt; Type: error #&gt; Regions with no neighbours included: #&gt; 289 627 1967 #&gt; Coefficients: (asymptotic standard errors) #&gt; Estimate Std. Error z value Pr(&gt;|z|) #&gt; (Intercept) -1.8431155 0.1519117 -12.1328 &lt; 2.2e-16 #&gt; log(1 + popinlabou) 0.7245486 0.0277532 26.1068 &lt; 2.2e-16 #&gt; log(1 + onlylessth) 0.1911611 0.0160471 11.9125 &lt; 2.2e-16 #&gt; log(1 + master) -0.0399508 0.0139103 -2.8720 0.004078 #&gt; log(1 + africaninl) 0.0761079 0.0068356 11.1341 &lt; 2.2e-16 #&gt; log(1 + asianinlab) -0.0115503 0.0070767 -1.6322 0.102645 #&gt; log(1 + hispanicin) 0.0346482 0.0127560 2.7162 0.006603 #&gt; medianage 0.0014076 0.0020147 0.6987 0.484768 #&gt; #&gt; Lambda: 0.29439, LR test value: 85.367, p-value: &lt; 2.22e-16 #&gt; Asymptotic standard error: 0.03168 #&gt; z-value: 9.2925, p-value: &lt; 2.22e-16 #&gt; Wald statistic: 86.351, p-value: &lt; 2.22e-16 #&gt; #&gt; Log likelihood: -1564.967 for error model #&gt; ML residual variance (sigma squared): 0.25155, (sigma: 0.50155) #&gt; Number of observations: 2124 #&gt; Number of parameters estimated: 10 #&gt; AIC: 3149.9, (AIC for lm: 3233.3) From the AIC, the spatial error model performs much better than the linear model (lower AIC basically means better fit). The \[\lambda\] Lambda value of 0.294 is also statistically significant, suggesting the error term is spatially autoregressive. While the model coefficients do not change much, most of them have higher absolute Z values, meaning more robust estimation with lower variance. # Derive the residuals from the regression. Need to handle those missed values seResiduals &lt;- rep(0, length(nycDat$popunemplo)) resIndex &lt;- serrRslt$residuals %&gt;% names() %&gt;% as.integer(); seResiduals[resIndex] &lt;- serrRslt$residuals # Test if there is spatial autocorrelation in the regression residuals (errors). nycNbList %&gt;% spdep::moran.test(seResiduals, ., zero.policy = TRUE) #&gt; #&gt; Moran I test under randomisation #&gt; #&gt; data: seResiduals #&gt; weights: . #&gt; n reduced by no-neighbour observations #&gt; #&gt; Moran I statistic standard deviate = -0.54657, p-value = 0.7077 #&gt; alternative hypothesis: greater #&gt; sample estimates: #&gt; Moran I statistic Expectation Variance #&gt; -0.0073092421 -0.0004625347 0.0001569199 Now, it is rather clear that there is no spatial autocorrelation in the residuals anymore as the Moran’s I is close to zero now. More importantly, the p-value is 0.71, meaning we cannot reject the hypothesis that the Moran’s I is zero. 4.2.2 Spatial Lag Model A spatial lag is a variable that essentially averages the neighboring values of a location (the value of each neighboring location is multiplied by the spatial weight and then the products are summed). It can be used to compare the neighboring values with those of the location itself. Which locations are defined as neighbors in this process is specified through a row-standardized spatial weights matrix in GeoDa and a list of standardized weights in spdep. By convention, the location at the center of its neighbors is not included in the definition of neighbors and is therefore set to zero. — Adapted from GeoDa Documentation For these spatial lags, we can use the spatial lag model to address the spatial autocorrelation in the dependent variable. \[ {\mathbf y} = ho_{\mathrm{Lag}} {\mathbf W}{\mathbf y} + {\mathbf X}{\mathbf  eta} + {\mathbf \varepsilon}, \] where \(ho_{\mathrm{Lag}}\) is a scalar spatial parameter, indicating how much a spatial feature is influenced by its neighbors. # use spdep package to run the spatial lag model # spatialreg::lagsarlm slmRslt &lt;- spatialreg::lagsarlm(log(popunemplo +1) ~ log(1+popinlabou) + log(1+onlylessth) + log(1+master) + log(1+africaninl) + log(1+asianinlab) + log(1+hispanicin) + medianage, data = nycDat, listw = nycNbList, zero.policy = TRUE, na.action = na.omit); summary(slmRslt) #&gt; #&gt; Call:spatialreg::lagsarlm(formula = log(popunemplo + 1) ~ log(1 + #&gt; popinlabou) + log(1 + onlylessth) + log(1 + master) + log(1 + #&gt; africaninl) + log(1 + asianinlab) + log(1 + hispanicin) + #&gt; medianage, data = nycDat, listw = nycNbList, na.action = na.omit, #&gt; zero.policy = TRUE) #&gt; #&gt; Residuals: #&gt; Min 1Q Median 3Q Max #&gt; -4.591905 -0.248899 0.053451 0.306993 1.797936 #&gt; #&gt; Type: lag #&gt; Regions with no neighbours included: #&gt; 289 627 1967 #&gt; Coefficients: (asymptotic standard errors) #&gt; Estimate Std. Error z value Pr(&gt;|z|) #&gt; (Intercept) -2.4911143 0.1626826 -15.3127 &lt; 2e-16 #&gt; log(1 + popinlabou) 0.7208913 0.0269525 26.7467 &lt; 2e-16 #&gt; log(1 + onlylessth) 0.1810895 0.0148579 12.1881 &lt; 2e-16 #&gt; log(1 + master) -0.0314152 0.0134174 -2.3414 0.01921 #&gt; log(1 + africaninl) 0.0713624 0.0059629 11.9678 &lt; 2e-16 #&gt; log(1 + asianinlab) -0.0150805 0.0063527 -2.3739 0.01760 #&gt; log(1 + hispanicin) 0.0287700 0.0114775 2.5066 0.01219 #&gt; medianage 0.0030659 0.0018591 1.6491 0.09912 #&gt; #&gt; Rho: 0.14127, LR test value: 54.515, p-value: 1.5421e-13 #&gt; Asymptotic standard error: 0.019469 #&gt; z-value: 7.2563, p-value: 3.979e-13 #&gt; Wald statistic: 52.654, p-value: 3.979e-13 #&gt; #&gt; Log likelihood: -1580.393 for lag model #&gt; ML residual variance (sigma squared): 0.25841, (sigma: 0.50834) #&gt; Number of observations: 2124 #&gt; Number of parameters estimated: 10 #&gt; AIC: 3180.8, (AIC for lm: 3233.3) #&gt; LM test for residual autocorrelation #&gt; test value: 31.043, p-value: 2.5238e-08 Similarly, the spatial lag model is much better than the linear mode, even though it is not as good as the spatial error model for this specific case. The spatial lag term \[ho\] or Rho is also statistically significant. # Derive the residuals from the regression. Need to handle those missed values slResiduals &lt;- rep(0, length(nycDat$popunemplo)) resIndex &lt;- slmRslt$residuals %&gt;% names() %&gt;% as.integer(); slResiduals[resIndex] &lt;- slmRslt$residuals # Test if there is spatial autocorrelation in the regression residuals (errors). nycNbList %&gt;% spdep::moran.test(slResiduals, ., zero.policy = TRUE) #&gt; #&gt; Moran I test under randomisation #&gt; #&gt; data: slResiduals #&gt; weights: . #&gt; n reduced by no-neighbour observations #&gt; #&gt; Moran I statistic standard deviate = 4.7, p-value = 1.301e-06 #&gt; alternative hypothesis: greater #&gt; sample estimates: #&gt; Moran I statistic Expectation Variance #&gt; 0.0584191174 -0.0004625347 0.0001569527 The under-performance of spatial lag model is also evident from the Moran’s I test. Residuals from spatial lag model still have statistically significant (p &lt; 0.01) spatial autocorrelation, although the Moran’s I of 0.06 is much smaller than 0.27 of the dependent variable. In fact, we can combine the spatial error and spatial lag models into a spatial simultaneous autoregression model or “SAC/SARAR” model. \[ {\mathbf y} = ho_{\mathrm{Lag}} {\mathbf W}{\mathbf y} + {\mathbf X}{\mathbf  eta} + {\mathbf u}, \qquad {\mathbf u} = \lambda_{\mathrm{Err}} {\mathbf W} {\mathbf u} + {\mathbf \varepsilon} \] This model can be estimated using spatialreg::sacsarlm but will not be discussed here. 4.3 Spatial Heterogeneity and Spatially Varying Coefficients Spatial heterogeneity exists when structural changes related to location exist in a dataset. In such cases, spatial regimes might be present, which are characterized by differing parameter values or functional forms (e.g., crime in certain regions might be structurally different from crime in other regions). Spatial heterogeneity can result in non-constant error variance (heteroskedasticity) across areas, especially when scale-related measurement errors are present. It can be difficult to distinguish from spatial dependence. — GeoDa Documentation There are two families of models that can nicely address spatial heterogeneity: geographically weighted regression (GWR) and Bayesian hierarchical spatial models. While GWR is more like an exploratory tool than a rigorous statistical analysis, it is rather easy to understand and can produce insightful visualizations. 4.3.1 Geographically Weighted Regression (GWR) Geographically Weighted Regression (GWR) is one of several spatial regression techniques used in geography and other disciplines to address spatial heterogeneity. GWR evaluates a local model of the variable or process that we are trying to understand or predict by fitting a regression equation to every feature in the dataset. GWR constructs these separate equations by incorporating the dependent and explanatory variables of the features falling within the neighborhood of each target feature or the k nearest neighbors. GWR should be applied to datasets with over several hundred features. It is not an appropriate method for small datasets and does not work with multipoint data. Geographically Weighted Regression can be used for a variety of applications, including the following: Is the relationship between educational attainment and income consistent across the study area? Do certain illness or disease occurrences increase with proximity to water features? What are the key variables that explain high forest fire frequency? Which habitats should be protected to encourage the reintroduction of an endangered species? Where are the districts where children are achieving high test scores? What characteristics seem to be associated? Where is each characteristic most important? Are the factors influencing higher cancer rates consistent across the study area? — ArcGIS Documentation Here we are going to do a basic GWR using the GWmodel package in R. First we need to estimate an optimal bandwidth that will define the local neighborhood for every spatial feature. Then spatial features within the neighborhood will be used to estimate a regression model for that particular feature. There are many different ways to define such “neighborhoods” or bandwidth. The code below is using an “adaptive” neighborhood, which is defined as the k nearest neighbors based on Euclidean distances. But then how do we know how many neighbors we should use for the local regression? Or what is best value for k? GWmodel::bw.gwr can help us search for such an optimal value based on the model fitness. With that bandwidth, we can conduct a basic GWR. require(GWmodel) # Remove all the NAs in the dataset nycDatNoNA &lt;- nycDat %&gt;% tidyr::drop_na() %&gt;% dplyr::filter(medianage != &quot;NA&quot;) nycDatNoNA$medianage %&lt;&gt;% as.numeric() # Estimate an optimal bandwidth bwVal &lt;- GWmodel::bw.gwr(log(popunemplo + 1) ~ log(1+popinlabou) + log(1+onlylessth) + log(1+master) + log(1+africaninl) + log(1+asianinlab) + log(1+hispanicin) + as.numeric(medianage), data = nycDatNoNA %&gt;% sf::as_Spatial(), approach = &#39;AICc&#39;, kernel = &#39;bisquare&#39;, adaptive = TRUE) #&gt; Take a cup of tea and have a break, it will take a few minutes. #&gt; -----A kind suggestion from GWmodel development group #&gt; Adaptive bandwidth (number of nearest neighbours): 1314 AICc value: 3056.162 #&gt; Adaptive bandwidth (number of nearest neighbours): 820 AICc value: 3010.612 #&gt; Adaptive bandwidth (number of nearest neighbours): 513 AICc value: 2977.403 #&gt; Adaptive bandwidth (number of nearest neighbours): 325 AICc value: 2943.909 #&gt; Adaptive bandwidth (number of nearest neighbours): 207 AICc value: 2925.297 #&gt; Adaptive bandwidth (number of nearest neighbours): 136 AICc value: 